def stamp(t):
 ms=round(t*1000);return f'{ms//3600000:02}:{ms//60000%60:02}:{ms//1000%60:02},{ms%1000:03}'
def assstamp(t):
 cs=round(t*100);return f'{cs//360000}:{cs//6000%60:02}:{cs//100%60:02}.{cs%100:02}'
with (P/'Quorum-Recordings.srt').open('w')as f:
 for i,c in enumerate(captions):f.write(f"{i+1}\n{stamp(c['start'])} --> {stamp(c['end'])}\n{c['text']}\n\n")
capnodes=''.join(f'''<div id="recorded-caption-{i}" class="clip caption" data-start="{c['start']}" data-duration="{c['end']-c['start']}" data-track-index="1"><span>{esc(c['text'])}</span></div>'''for i,c in enumerate(captions))
(P/'compositions/captions.html').write_text('<template><style>#captions{position:relative;width:100%;height:100%}</style><div id="captions" data-composition-id="captions" data-width="1920" data-height="1080" data-duration="180">'+capnodes+"</div><script>const tl=gsap.timeline({paused:true});window.__timelines['captions']=tl;</script></template>")
labels=[(20,45,'PART 1 · RECORDED SUPPLIER WORKFLOW'),(45,72,'EARLIER RECORDING · ILLUSTRATIVE FIELDS VARY'),(72,110,'PART 2 · READ-ONLY BID REVIEW'),(110,134,'UNTITLED VIDEO · COMMITTEE + MEMBER REGISTRATION'),(134,142,'PART 2 · EVALUATION INTEGRITY'),(105,110,'SEPARATE LIVE CHECK: MUSE-SPARK-1.3 · SOURCE QUOTES VERIFIED')]
def mount(name,start,duration):return f'<div id="{name}" class="clip scene" data-composition-id="{name}" data-composition-src="compositions/{name}.html" data-start="{start}" data-duration="{duration}" data-width="1920" data-height="1080" data-track-index="0" data-track-kind="graphics"></div>'
footage='<div id="recorded-workflows" class="clip footage-scene" data-start="20" data-duration="122" data-track-index="0" data-track-kind="video"><video id="actual-recordings" src="assets/recorded-workflows.mp4" muted playsinline data-media-start="0"></video></div>'
# Time the video itself rather than a timed wrapper (core's media ownership rule).
footage='<video id="actual-recordings" class="clip" src="assets/recorded-workflows.mp4" data-start="20" data-duration="122" data-media-start="0" data-track-index="0" data-track-kind="video" muted playsinline style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover"></video>'
privacy='<div id="privacy-note" class="clip" data-start="28" data-duration="17" data-track-index="2" style="position:absolute;left:699px;top:781px;font-size:28px;color:white;z-index:45">Identifying details redacted</div>'
labelnodes=privacy+''.join(f'<div id="recording-label-{i}" class="clip recorded-label" data-start="{a}" data-duration="{b-a}" data-track-index="2" style="top:{95 if i==5 else 38}px">{esc(t)}</div>'for i,(a,b,t)in enumerate(labels))
def root(filename,cid,duration,children,audio='',directory=P):
 (directory/filename).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=1920,height=1080"><script src="assets/gsap.min.js"></script><style>{style}#{cid}{{position:relative;width:100%;height:100%;overflow:hidden}}</style></head><body><div id="{cid}" data-composition-id="{cid}" data-duration="{duration}" data-width="1920" data-height="1080" data-fps="30">{children}{audio}</div><script>const tl=gsap.timeline({{paused:true}});tl.to('#{cid}',{{opacity:1,duration:{duration},ease:'none'}},0);window.__timelines['{cid}']=tl;</script></body></html>''')
# Each recorded chapter is a real sub-composition with its own footage + labels.
recorded=[]
for name,start,duration,media in [('supplier',20,25,0),('workflow',45,27,25),('review',72,38,52),('committee',110,32,90)]:
 local_labels=''
 for j,(a,b,text) in enumerate(labels):
  left=max(a,start);right=min(b,start+duration)
  if right>left:
   local_labels+=f'<div id="{name}-label-{j}" class="clip recorded-label" data-start="{left-start}" data-duration="{right-left}" data-track-index="2" style="top:{95 if j==5 else 38}px">{esc(text)}</div>'
 if name=='supplier':local_labels+=privacy.replace('id="privacy-note"','id="supplier-privacy"').replace('data-start="28"','data-start="8"')
 markup=f'<template><style>#{name}{{position:relative;width:100%;height:100%;overflow:hidden;background:#101217}}</style><div id="{name}" data-composition-id="{name}" data-width="1920" data-height="1080" data-duration="{duration}"><video id="{name}-video" class="clip" src="assets/recorded-workflows.mp4" data-start="0" data-duration="{duration}" data-media-start="{media}" data-track-index="0" muted playsinline style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover"></video>{local_labels}</div><script>const tl=gsap.timeline({{paused:true}});window.__timelines[\'{name}\']=tl;</script></template>'
 (P/'compositions'/f'{name}.html').write_text(markup);recorded.append(mount(name,start,duration))
root('index.html','main',180,mount('stakes',0,20)+''.join(recorded)+mount('boundary',142,28)+mount('close',170,10)+mount('captions',0,180).replace('data-track-index="0" data-track-kind="graphics"','data-track-index="3" data-track-kind="captions"'),'<audio id="recorded-master" src="assets/master.wav" data-start="0" data-duration="180" data-track-index="4"></audio>')
